@dataclass(frozen=True, slots=True)
class ValidationCheckV1:
    check_id: str
    passed: bool
    detail: str


@dataclass(frozen=True, slots=True)
class ValidationReportV1:
    domain: str
    checks: tuple[ValidationCheckV1, ...]

    @property
    def passed(self) -> bool:
        return bool(self.checks) and all(check.passed for check in self.checks)

    def assert_passed(self) -> None:
        failed = [check for check in self.checks if not check.passed]
        if failed:
            raise ContractValidationError(
                ReasonCode.VALIDATION_FAILED,
                "; ".join(f"{item.check_id}: {item.detail}" for item in failed),
            )


class CoverageTerminalStatusV1(StrEnum):
    PASS = "PASS"
    FAIL = "FAIL"


@dataclass(frozen=True, slots=True)
class CoverageRowV1:
    row_id: str
    category: str
    domain: str
    predicate: str
    subject_ref: str
    test_path: str
    independent_validator: str
    terminal_status: CoverageTerminalStatusV1
    owner: str
    producer: str
    consumer_refs: tuple[str, ...]
    no_orphan_disposition: str

    def __post_init__(self) -> None:
        for name in (
            "row_id",
            "category",
            "domain",
            "predicate",
            "subject_ref",
            "test_path",
            "independent_validator",
            "owner",
            "producer",
            "no_orphan_disposition",
        ):
            value = getattr(self, name)
            if not isinstance(value, str) or not value:
                raise ContractValidationError(
                    ReasonCode.INCOMPLETE_CONTRACT,
                    f"coverage row {name} must be nonempty text",
                )
        validate_relative_path(self.test_path)
        validate_relative_path(self.independent_validator)
        if not isinstance(self.terminal_status, CoverageTerminalStatusV1):
            raise ContractValidationError(
                ReasonCode.INVALID_CONTRACT,
                "coverage terminal status must be typed",
            )
        if (
            not isinstance(self.consumer_refs, tuple)
            or not self.consumer_refs
            or any(
                not isinstance(value, str) or not value
                for value in self.consumer_refs
            )
            or len(self.consumer_refs) != len(set(self.consumer_refs))
        ):
            raise ContractValidationError(
                ReasonCode.INVALID_CONTRACT,
                f"coverage row has no exact consumer route: {self.row_id}",
            )


@dataclass(frozen=True, slots=True)
class TrancheACoverageManifestV1:
    rows: tuple[CoverageRowV1, ...]

    def __post_init__(self) -> None:
        if (
            not isinstance(self.rows, tuple)
            or not self.rows
            or any(not isinstance(row, CoverageRowV1) for row in self.rows)
        ):
            raise ContractValidationError(
                ReasonCode.INCOMPLETE_CONTRACT,
                "coverage manifest requires typed immutable rows",
            )
        row_ids = tuple(row.row_id for row in self.rows)
        if len(row_ids) != len(set(row_ids)):
            raise ContractValidationError(
                ReasonCode.INVALID_CONTRACT,
                "coverage manifest contains duplicate row identities",
            )

    @property
    def executed_counts(self) -> MappingProxyType:
        counts = Counter(
            row.category
            for row in self.rows
            if row.terminal_status is CoverageTerminalStatusV1.PASS
        )
        counts["total_rows"] = sum(counts.values())
        return MappingProxyType(dict(sorted(counts.items())))


@dataclass(frozen=True, slots=True)
class _CoverageBlueprintV1:
    row_id: str
    category: str
    domain: str
    predicate: str
    subject_ref: str
    test_path: str
    independent_validator: str
    owner: str = "QKUComputationControlPlaneV1"
    producer: str = "TrancheACoverageManifestV1"
    consumer_refs: tuple[str, ...] = (
        "QKU_COMPUTATION_CONTROL_PLANE_PRIMARY_VALIDATION",
        "QKU_COMPUTATION_CONTROL_PLANE_INDEPENDENT_VALIDATION",
    )
    no_orphan_disposition: str = "VALIDATED_AND_CONSUMED"


def _control_test_path(domain: str, predicate: str) -> str:
    return (
        "tests/stage1_prediction_markets/qku_computation_control_plane/"
        f"{domain}/test_{predicate.replace('-', '_')}.py"
    )


def _coverage_blueprint() -> tuple[_CoverageBlueprintV1, ...]:
    rows: list[_CoverageBlueprintV1] = []
    for control_id, domain, predicate in TRANCHE_A_CONTROL_ROWS:
        rows.append(
            _CoverageBlueprintV1(
                row_id=control_id,
                category="closure_rows",
                domain=domain,
                predicate=predicate,
                subject_ref=control_id,
                test_path=_control_test_path(domain, predicate),
                independent_validator=INDEPENDENT_VALIDATOR_BY_DOMAIN[domain],
            )
        )
    for index, path in enumerate(TRANCHE_A_PRODUCTION_CORE_PATHS, 1):
        rows.append(
            _CoverageBlueprintV1(
                row_id=f"ST12A-REPOSITORY::{index:02d}",
                category="repository_dispositions",
                domain="architecture",
                predicate="owned-production-path-present-and-consumed",
                subject_ref=path,
                test_path=_control_test_path(
                    "architecture",
                    "repository-file-closure",
                ),
                independent_validator=INDEPENDENT_VALIDATOR_BY_DOMAIN[
                    "architecture"
                ],
            )
        )
    for policy in PARAMETER_POLICIES:
        rows.append(
            _CoverageBlueprintV1(
                row_id=policy.parameter_id,
                category="parameter_policy_rows",
                domain="architecture",
                predicate="parameter-policy-resolves-exact-certified-row",
                subject_ref=policy.parameter_id,
                test_path=_control_test_path(
                    "architecture",
                    "step12-tranche-readiness",
                ),
                independent_validator=INDEPENDENT_VALIDATOR_BY_DOMAIN[
                    "architecture"
                ],
            )
        )
    for math_id in MATH_IDS:
        domain = "quantum" if math_id in {"MATH-46", "MATH-47", "MATH-48", "MATH-49"} else "architecture"
        validator = INDEPENDENT_VALIDATOR_BY_DOMAIN[domain]
        rows.append(
            _CoverageBlueprintV1(
                row_id=f"ST12A-MATH-SPEC::{math_id}",
                category="mathematical_specifications",
                domain=domain,
                predicate="implementation-and-typed-io-contract-closed",
                subject_ref=math_id,
                test_path=_control_test_path(
                    "architecture",
                    "schema-cross-consistency",
                ),
                independent_validator=validator,
            )
        )
        oracle = ORACLE_BY_MATH_ID[math_id]
        rows.append(
            _CoverageBlueprintV1(
                row_id=f"ST12A-ORACLE::{oracle.oracle_id}",
                category="independent_oracle_specifications",
                domain=domain,
                predicate="independent-oracle-lineage-closed",
                subject_ref=oracle.oracle_id,
                test_path=_control_test_path(
                    "architecture",
                    "no-orphan-consumers",
                ),
                independent_validator=validator,
            )
        )
        vector = GOLDEN_VECTOR_BY_MATH_ID[math_id]
        rows.append(
            _CoverageBlueprintV1(
                row_id=f"ST12A-VECTOR::{vector.vector_id}",
                category="golden_vectors_and_invariants",
                domain=domain,
                predicate="golden-vector-lineage-and-comparison-closed",
                subject_ref=vector.vector_id,
                test_path=_control_test_path(
                    "architecture",
                    "schema-cross-consistency",
                ),
                independent_validator=validator,
            )
        )
    for control_id, domain, predicate in TRANCHE_A_CONTROL_ROWS:
        path = _control_test_path(domain, predicate)
        rows.append(
            _CoverageBlueprintV1(
                row_id=f"ST12A-TEST::{control_id}",
                category="test_rows",
                domain=domain,
                predicate="certified-domain-test-path-present",
                subject_ref=path,
                test_path=path,
                independent_validator=INDEPENDENT_VALIDATOR_BY_DOMAIN[domain],
            )
        )
    for row_name, domain, test_path in _SHARED_VALIDATION_TEST_ROWS:
        validator = INDEPENDENT_VALIDATOR_BY_DOMAIN[domain]
        rows.append(
            _CoverageBlueprintV1(
                row_id=f"ST12A-TEST::SHARED::{row_name}",
                category="test_rows",
                domain=domain,
                predicate="shared-centralized-validation-test-present",
                subject_ref=test_path,
                test_path=test_path,
                independent_validator=validator,
            )
        )
    for domain, validator in INDEPENDENT_VALIDATOR_BY_DOMAIN.items():
        primary_path = "tools/validate_qku_computation_control_plane.py"
        rows.extend(
            (
                _CoverageBlueprintV1(
                    row_id=f"ST12A-COMMAND::PRIMARY::{domain}",
                    category="validation_command_rows",
                    domain=domain,
                    predicate=(
                        "python -B tools/validate_qku_computation_control_plane.py "
                        f"--domain {domain}"
                    ),
                    subject_ref=primary_path,
                    test_path=primary_path,
                    independent_validator=validator,
                ),
                _CoverageBlueprintV1(
                    row_id=f"ST12A-COMMAND::INDEPENDENT::{domain}",
                    category="validation_command_rows",
                    domain=domain,
                    predicate=f"python -B {validator}",
                    subject_ref=validator,
                    test_path=validator,
                    independent_validator=validator,
                ),
            )
        )
    for rule in SOURCE_CLAIM_BINDING_RULES:
        rows.append(
            _CoverageBlueprintV1(
                row_id=rule.binding_rule_id,
                category="source_claim_binding_rules",
                domain="source",
                predicate="exact-source-claim-binding-fail-closed",
                subject_ref=rule.binding_rule_id,
                test_path=_control_test_path("source", "fact-atomicity"),
                independent_validator=INDEPENDENT_VALIDATOR_BY_DOMAIN["source"],
            )
        )
    return tuple(rows)


def _coverage_predicate_passes(
    row: _CoverageBlueprintV1,
    *,
    domain_results: dict[str, bool] | None = None,
) -> bool:
    if not (REPO_ROOT / row.test_path).is_file():
        return False
    if not (REPO_ROOT / row.independent_validator).is_file():
        return False
    if row.category == "closure_rows":
        if domain_results is None:
            return validate_domain(row.domain).passed
        return domain_results[row.domain]
    if row.category == "repository_dispositions":
        return (
            row.subject_ref in TRANCHE_A_PRODUCTION_CORE_PATHS
            and (REPO_ROOT / row.subject_ref).is_file()
        )
    if row.category == "parameter_policy_rows":
        try:
            resolved = ParameterPolicyResolverV1.resolve(row.subject_ref)
        except ComputationControlPlaneError:
            return False
        return resolved.parameter_id == row.subject_ref and resolved.used_day1_seed
    if row.category == "mathematical_specifications":
        return (
            row.subject_ref in IMPLEMENTATION_REGISTRY
            and row.subject_ref in MATH_IO_CONTRACTS
            and callable(IMPLEMENTATION_REGISTRY[row.subject_ref].callable)
        )
    if row.category == "independent_oracle_specifications":
        return any(
            oracle.oracle_id == row.subject_ref
            and oracle.math_spec_id in IMPLEMENTATION_REGISTRY
            and not oracle.production_import_allowed
            and not oracle.primary_validator_import_allowed
            for oracle in ORACLE_BY_MATH_ID.values()
        )
    if row.category == "golden_vectors_and_invariants":
        return any(
            vector.vector_id == row.subject_ref
            and vector.math_spec_id in IMPLEMENTATION_REGISTRY
            and vector.oracle_id
            == ORACLE_BY_MATH_ID[vector.math_spec_id].oracle_id
            and not vector.production_import_allowed
            for vector in GOLDEN_VECTOR_BY_MATH_ID.values()
        )
    if row.category in {"test_rows", "validation_command_rows"}:
        return True
    if row.category == "source_claim_binding_rules":
        return any(
            rule.binding_rule_id == row.subject_ref
            and not rule.source_pack_as_primary_allowed
            and not rule.broad_regex_or_alias_matching_allowed
            and not rule.codex_source_selection_allowed
            for rule in SOURCE_CLAIM_BINDING_RULES
        )
    return False


def build_tranche_a_coverage_manifest(
    *,
    predicate_overrides: MappingProxyType | dict[str, bool] | None = None,
) -> TrancheACoverageManifestV1:
    overrides = {} if predicate_overrides is None else dict(predicate_overrides)
    blueprint = _coverage_blueprint()
    domain_results = {
        domain: validate_domain(domain).passed
        for domain in INDEPENDENT_VALIDATOR_BY_DOMAIN
    }
    unexpected_overrides = set(overrides) - {row.row_id for row in blueprint}
    if unexpected_overrides:
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT,
            f"coverage override has unexpected rows: {sorted(unexpected_overrides)!r}",
        )
    rows = tuple(
        CoverageRowV1(
            row_id=row.row_id,
            category=row.category,
            domain=row.domain,
            predicate=row.predicate,
            subject_ref=row.subject_ref,
            test_path=row.test_path,
            independent_validator=row.independent_validator,
            terminal_status=(
                CoverageTerminalStatusV1.PASS
                if overrides.get(
                    row.row_id,
                    _coverage_predicate_passes(
                        row,
                        domain_results=domain_results,
                    ),
                )
                else CoverageTerminalStatusV1.FAIL
            ),
            owner=row.owner,
            producer=row.producer,
            consumer_refs=row.consumer_refs,
            no_orphan_disposition=row.no_orphan_disposition,
        )
        for row in blueprint
    )
    return validate_tranche_a_coverage_manifest(rows)


def validate_tranche_a_coverage_manifest(
    rows: tuple[CoverageRowV1, ...] | TrancheACoverageManifestV1,
) -> TrancheACoverageManifestV1:
    manifest = rows if isinstance(rows, TrancheACoverageManifestV1) else TrancheACoverageManifestV1(rows)
    expected = _coverage_blueprint()
    domain_results = {
        domain: validate_domain(domain).passed
        for domain in INDEPENDENT_VALIDATOR_BY_DOMAIN
    }
    expected_ids = tuple(row.row_id for row in expected)
    actual_ids = tuple(row.row_id for row in manifest.rows)
    if actual_ids != expected_ids:
        missing = tuple(row_id for row_id in expected_ids if row_id not in actual_ids)
        unexpected = tuple(row_id for row_id in actual_ids if row_id not in expected_ids)
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT,
            "coverage closure mismatch: "
            f"missing={missing!r}; unexpected={unexpected!r}",
        )
    for actual, blueprint in zip(manifest.rows, expected, strict=True):
        for name in (
            "row_id",
            "category",
            "domain",
            "predicate",
            "subject_ref",
            "test_path",
            "independent_validator",
            "owner",
            "producer",
            "consumer_refs",
            "no_orphan_disposition",
        ):
            if getattr(actual, name) != getattr(blueprint, name):
                raise ContractValidationError(
                    ReasonCode.INVALID_CONTRACT,
                    f"coverage row metadata changed: {actual.row_id}:{name}",
                )
        if (
            actual.terminal_status is not CoverageTerminalStatusV1.PASS
            or not _coverage_predicate_passes(
                blueprint,
                domain_results=domain_results,
            )
        ):
            raise ContractValidationError(
                ReasonCode.VALIDATION_FAILED,
                f"coverage predicate failed: {actual.row_id}:{actual.predicate}",
            )
    return manifest


def _check(check_id: str, condition: bool, detail: str) -> ValidationCheckV1:
    return ValidationCheckV1(check_id, bool(condition), detail)


def validate_snapshot_contract(snapshot: FormulaRuntimeSnapshotV1) -> None:
    if snapshot.activated:
        raise ContractValidationError(
            ReasonCode.RUNTIME_EFFECT_FORBIDDEN,
            "snapshot activation is outside Tranche A",
        )
    if len(snapshot.source_epoch_ids) != len(set(snapshot.source_epoch_ids)):
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT, "snapshot source epochs must be unique"
        )


def validate_transaction_contract(transaction: TransactionEnvelopeV1) -> None:
    if transaction.committed:
        raise ContractValidationError(
            ReasonCode.RUNTIME_EFFECT_FORBIDDEN,
            "durable commit is outside Tranche A",
        )
    if transaction.relative_output_path is not None:
        validate_relative_path(transaction.relative_output_path)


def validate_operation_contract_closure(
    operations: tuple[OperationContractV1, ...] = TRANCHE_A_OPERATION_CONTRACTS,
) -> tuple[OperationContractV1, ...]:
    if (
        not isinstance(operations, tuple)
        or len(operations) != len(TRANCHE_A_OPERATION_CONTRACTS)
        or any(
            not isinstance(operation, OperationContractV1)
            for operation in operations
        )
        or operations != TRANCHE_A_OPERATION_CONTRACTS
    ):
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT,
            "operation closure must exactly equal the certified typed roster",
        )
    for attribute in (
        "operation_id",
        "operation_name",
        "request_type",
        "response_type",
    ):
        values = tuple(getattr(operation, attribute) for operation in operations)
        if len(set(values)) != len(operations):
            raise ContractValidationError(
                ReasonCode.INVALID_CONTRACT,
                f"operation closure has a collision in {attribute}",
            )
    for operation in operations:
        if (
            operation.runtime_effect_authorized
            or operation.provider_effect_authorized
            or operation.capability_class
            is not OperationCapabilityClass.CONTRACT_DEFINITION_ONLY
            or operation.side_effect_class
            is not OperationSideEffectClass.PURE_OR_APPEND_ONLY_NON_PROVIDER_EFFECT
            or operation.schema_version != "1.4.0"
            or tuple(field.name for field in operation.request_fields)
            != tuple(field.name for field in fields(operation.request_model))
            or tuple(field.name for field in operation.response_fields)
            != tuple(field.name for field in fields(operation.response_model))
        ):
            raise ContractValidationError(
                ReasonCode.RUNTIME_EFFECT_FORBIDDEN,
                f"operation is not contract-only: {operation.operation_id}",
            )
    return operations


def _contract_only_models_are_valid() -> bool:
    configuration = ConfigurationEnvelopeV1(
        "ST12A_CONFIGURATION_CONTRACT",
        "1.0",
        ("ST10-PARAM::0083",),
    )
    health = HealthEnvelopeV1(
        "QKUComputationControlPlaneV1",
        HealthState.HEALTHY_CONTRACT,
        ("STATIC_CONTRACT_VALIDATED",),
    )
    supervision = SupervisionEnvelopeV1(
        "ST12A_SUPERVISION_CONTRACT",
        ("QKUComputationControlPlaneV1",),
    )
    fallback = FallbackEnvelopeV1(
        "ST12A_FALLBACK_CONTRACT",
        (ReasonCode.CAPABILITY_DENIED.value,),
        "NO_EFFECT_FAIL_CLOSED",
    )
    snapshot = FormulaRuntimeSnapshotV1(
        "ST12A_SNAPSHOT_CONTRACT",
        "ST12A_SPECIFICATION_CONTRACT",
        "1.1R1",
        "1.0",
        "CERTIFIED_STEP11_PARAMETER_POLICY",
        ("ST10-SOURCE::01",),
        SnapshotState.CONTRACT_ONLY,
    )
    transaction = TransactionEnvelopeV1(
        "ST12A_TRANSACTION_CONTRACT",
        snapshot.snapshot_id,
        "validation/st12a-contract-output.json",
    )
    receipt = ComputationExecutionReceiptV1(
        "ST12A_RECEIPT_CONTRACT",
        snapshot.specification_id,
        "MATH-01::1.1R1",
        "input-v1",
        '{"contract_only":true}',
    )
    operation = TRANCHE_A_OPERATION_CONTRACTS[0]
    moment = datetime(2026, 7, 24, 12, tzinfo=UTC)
    operation_context = ComputationContextKeyV1(
        "ST12A_OPERATION_CONTEXT",
        moment,
        moment,
        "ST10-SOURCE::01",
        "input-v1",
        timedelta(minutes=1),
    )
    request = operation.bind_request(
        request_id="ST12A_OPERATION_REQUEST",
        operation_name="resolve_identity",
        requested_at=moment,
        principal_id="ST12A_PRINCIPAL",
        capability_bundle_id="ST12A_DEFAULT_DENY_BUNDLE",
        context=operation_context,
        idempotency_key="ECONOMIC::ST12A_OPERATION_REQUEST",
        traceparent="00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01",
        tracestate="",
        identity_query=TypedValueRecordV1(
            (
                TypedValueV1(
                    "formula_id",
                    TypedValueKindV1.TEXT,
                    "FORMULA_QKU",
                    "identifier",
                    "RP5C",
                ),
            )
        ),
    )
    response = operation.bind_response(
        request,
        response_id="ST12A_OPERATION_RESPONSE",
        operation_name="resolve_identity",
        request_id=request.request_id,
        completed_at=moment,
        status=OperationStatusV1.SUCCEEDED,
        context=operation_context,
        warnings=(),
        blocker_codes=(),
        receipt_refs=("RP5C_IDENTITY_00000001",),
        traceparent=request.traceparent,
        tracestate=request.tracestate,
        identity_resolution=IdentityResolutionV1(
            "RP5C_IDENTITY_00000001",
            "RETURN_CANONICAL_IDENTITY_VIEW",
            ("RP5C_IDENTITY_00000001",),
        ),
    )
    validate_snapshot_contract(snapshot)
    validate_transaction_contract(transaction)
    validate_operation_contract_closure()
    return (
        not configuration.mutable_runtime
        and health.state is HealthState.HEALTHY_CONTRACT
        and not supervision.process_supervision_enabled
        and not fallback.permits_new_writes
        and not snapshot.activated
        and not transaction.committed
        and isinstance(request, OperationRequestEnvelopeV1)
        and isinstance(response, OperationResponseEnvelopeV1)
        and operation.request_json(request)
        and operation.response_json(response)
        and not any(
            (
                receipt.provider_effect,
                receipt.private_state_effect,
                receipt.replay_or_paper_effect,
                receipt.order_effect,
                receipt.qpu_effect,
            )
        )
    )


def _package_ast() -> tuple[tuple[Path, ast.Module], ...]:
    trees: list[tuple[Path, ast.Module]] = []
    for relative in PRODUCTION_CORE_PATHS:
        path = REPO_ROOT / relative
        trees.append(
            (
                path,
                ast.parse(path.read_text(encoding="utf-8"), filename=str(path)),
            )
        )
    return tuple(trees)


def _no_runtime_topology() -> bool:
    forbidden_modules = {
        "asyncio",
        "http",
        "multiprocessing",
        "socket",
        "sqlite3",
        "subprocess",
        "threading",
        "urllib",
    }
    forbidden_file_names = {
        "backup.py",
        "database.py",
        "runtime.py",
        "supervision.py",
    }
    package = REPO_ROOT / Path(PRODUCTION_CORE_PATHS[0]).parent
    if forbidden_file_names & {path.name for path in package.glob("*.py")}:
        return False
    for path, tree in _package_ast():
        for node in ast.walk(tree):
            if isinstance(node, ast.Import) and any(
                alias.name.split(".", 1)[0] in forbidden_modules
                for alias in node.names
            ):
                return False
            if (
                isinstance(node, ast.ImportFrom)
                and node.module
                and node.module.split(".", 1)[0] in forbidden_modules
            ):
                if not (
                    path.name == "parameter_policy.py"
                    and node.module == "threading"
                    and {alias.name for alias in node.names} <= {"Condition", "Lock"}
                ):
                    return False
    return True


def _no_dynamic_import_or_unsafe_deserialization() -> bool:
    forbidden_names = {"__import__", "compile", "eval", "exec"}
    forbidden_attributes = {
        ("importlib", "import_module"),
        ("pickle", "load"),
        ("pickle", "loads"),
    }
    for _, tree in _package_ast():
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            if isinstance(node.func, ast.Name) and node.func.id in forbidden_names:
                return False
            if (
                isinstance(node.func, ast.Attribute)
                and isinstance(node.func.value, ast.Name)
                and (node.func.value.id, node.func.attr) in forbidden_attributes
            ):
                return False
    return True


def _parameter_seed_resolution_valid() -> bool:
    for policy in PARAMETER_POLICIES:
        resolved = ParameterPolicyResolverV1.resolve(policy.parameter_id)
        if (
            resolved.parameter_id != policy.parameter_id
            or resolved.parameter_audit_id != policy.parameter_audit_id
            or resolved.parameter_symbol != policy.parameter_symbol
            or resolved.value
            != policy.effective_day1_seed_value_or_resolution_rule
            or resolved.unit_or_basis != policy.effective_unit_or_basis
            or resolved.resolution_class != policy.effective_resolution_class
            or resolved.authority_class
            != policy.effective_default_authority_class
            or resolved.fallback
            != policy.effective_fallback_behavior_when_value_unavailable
            or resolved.owner_editability
            != policy.effective_owner_dashboard_editability_class
            or not resolved.used_day1_seed
        ):
            return False
    return True


def _st12f_parameter_registry_integrity_checks_v1(
    registry: ST12FParameterRegistryV1,
    receipt: _ST12FParameterRegistryBuildReceiptV1,
) -> tuple[ValidationCheckV1, ...]:
    expected_shards = tuple(
        f"st12f_parameter_rows_{start:04d}_{start + 319:04d}.jsonl"
        for start in range(1, 3841, 320)
    )
    expected_resources = (
        "st12f_parameter_resources_manifest.json",
        *expected_shards,
    )
    expected_distribution = (
        ("STATIC_OR_DETERMINISTIC_RULE", 2668),
        ("RUNTIME_TYPED_BINDING", 300),
        ("EXPLICIT_FAIL_CLOSED_POLICY", 78),
        ("OFFLINE_CALIBRATION_OR_BOUNDED_OPTIMIZATION", 38),
        ("OFFLINE_CALIBRATION_REQUIRED", 12),
    )

    def recursively_immutable(value: object) -> bool:
        if type(value) is MappingProxyType:
            return all(
                type(key) is str and recursively_immutable(item)
                for key, item in value.items()
            )
        if type(value) is tuple:
            return all(recursively_immutable(item) for item in value)
        return type(value) in {str, bool, int, float, type(None)}

    def frozen_slots_rows(rows: tuple[object, ...], expected_type: type) -> bool:
        parameters = getattr(expected_type, "__dataclass_params__", None)
        return (
            parameters is not None
            and parameters.frozen
            and "__slots__" in expected_type.__dict__
            and all(type(row) is expected_type for row in rows)
        )

    registry_type_valid = (
        type(registry) is ST12FParameterRegistryV1
        and getattr(ST12FParameterRegistryV1, "__dataclass_params__").frozen
        and "__slots__" in ST12FParameterRegistryV1.__dict__
    )
    receipt_parameters = getattr(
        _ST12FParameterRegistryBuildReceiptV1,
        "__dataclass_params__",
        None,
    )
    receipt_type_valid = (
        type(receipt) is _ST12FParameterRegistryBuildReceiptV1
        and receipt_parameters is not None
        and receipt_parameters.frozen
        and "__slots__" in _ST12FParameterRegistryBuildReceiptV1.__dict__
    )
    policies = registry.parameter_policies if registry_type_valid else ()
    bindings = registry.application_bindings if registry_type_valid else ()
    calibrations = registry.calibration_policies if registry_type_valid else ()
    policy_ids = tuple(row.parameter_id for row in policies)
    binding_parameter_ids = tuple(row.parameter_id for row in bindings)
    binding_ids = tuple(row.binding_id for row in bindings)
    calibration_ids = tuple(row.parameter_id for row in calibrations)
    resolution_counts = Counter(
        row.implementation_resolution_kind for row in policies
    )
    actual_distribution = tuple(
        (kind, resolution_counts[kind]) for kind, _ in expected_distribution
    )

    roster_and_bounds_valid = receipt_type_valid and (
        receipt.resource_filenames == expected_resources
        and receipt.shard_filenames == expected_shards
        and receipt.resource_count == 13
        and receipt.shard_count == 12
        and 0 < receipt.manifest_byte_count <= 65536
        and 0 < receipt.maximum_shard_byte_count < 2100000
        and 0 < receipt.maximum_physical_line_byte_count <= 65536
    )
    populations_valid = receipt_type_valid and (
        receipt.policy_count == len(policies) == 3096
        and receipt.binding_count == len(bindings) == 3096
        and receipt.calibration_count == len(calibrations) == 50
        and receipt.explicit_absence_count == 3046
        and receipt.canonical_value_owner == "ComputationParameterPolicyV1"
    )
    distribution_valid = receipt_type_valid and (
        receipt.resolution_distribution == expected_distribution
        and actual_distribution == expected_distribution
    )
    ordered_rows_valid = (
        type(policies) is tuple
        and type(bindings) is tuple
        and type(calibrations) is tuple
        and frozen_slots_rows(policies, ST12FParameterPolicyRowV1)
        and frozen_slots_rows(bindings, ST12FParameterApplicationBindingV1)
        and frozen_slots_rows(calibrations, ST12FCalibrationOptimizerPolicyV1)
    )
    indexes = (
        registry.policy_by_parameter_id,
        registry.binding_by_parameter_id,
        registry.binding_by_binding_id,
        registry.calibration_by_parameter_id,
    )
    index_shapes_valid = (
        all(type(index) is MappingProxyType for index in indexes)
        and tuple(len(index) for index in indexes) == (3096, 3096, 3096, 50)
    )
    index_identity_valid = (
        tuple(registry.policy_by_parameter_id) == policy_ids
        and tuple(registry.binding_by_parameter_id) == binding_parameter_ids
        and tuple(registry.binding_by_binding_id) == binding_ids
        and tuple(registry.calibration_by_parameter_id) == calibration_ids
        and len(set(policy_ids)) == len(policy_ids)
        and len(set(binding_ids)) == len(binding_ids)
        and all(
            registry.policy_by_parameter_id[row.parameter_id] is row
            for row in policies
        )
        and all(
            registry.binding_by_parameter_id[row.parameter_id] is row
            and registry.binding_by_binding_id[row.binding_id] is row
            for row in bindings
        )
        and all(
            registry.calibration_by_parameter_id[row.parameter_id] is row
            for row in calibrations
        )
    )
    recursively_frozen_valid = all(
        recursively_immutable(getattr(row, field.name))
        for row in (*policies, *bindings, *calibrations)
        for field in fields(row)
    )
    canonical_owner_and_fabrication_valid = (
        all(
            row.canonical_value_owner == "ComputationParameterPolicyV1"
            and row.runtime_value_fabrication_allowed is False
            and row.second_value_owner_allowed is False
            for row in policies
        )
        and all(
            row.canonical_value_owner == "ComputationParameterPolicyV1"
            and row.consumer_may_browse_or_invent_value is False
            and row.second_parameter_value_owner_prohibited is True
            for row in bindings
        )
    )
    range_metadata_not_runtime_valid = all(
        type(policy.search_or_tuning_range) is MappingProxyType
        and type(policy.initial_default_or_resolution_rule) is str
        and binding.effective_range_field
        == "st12f_currentized_reference_range_or_structural_constraint"
        and binding.effective_rule_field
        == "st12f_currentized_day1_seed_or_resolution_rule"
        for policy, binding in zip(policies, bindings, strict=True)
    )
    policy_binding_joins_valid = (
        len(policies) == len(bindings)
        and len({row.application_contract for row in bindings}) == 1
        and len({row.complete_canonical_schema_ref for row in bindings}) == 1
        and len(
            {
                binding.resolution_path
                for policy, binding in zip(policies, bindings, strict=True)
                if policy.implementation_resolution_kind == "RUNTIME_TYPED_BINDING"
            }
        )
        == 1
        and len(
            {
                binding.resolution_path
                for policy, binding in zip(policies, bindings, strict=True)
                if policy.implementation_resolution_kind != "RUNTIME_TYPED_BINDING"
            }
        )
        == 1
        and all(
            policy.parameter_id == binding.parameter_id
            and policy.parameter_symbol == binding.parameter_symbol
            and policy.policy_consumer_owner == binding.policy_consumer_owner
            and policy.master_plan_section_id == binding.master_plan_section_id
            and binding.family_evidence_binding_ref
            == policy.source_and_evidence_requirements[
                "family_evidence_binding_ref"
            ]
            and binding.binding_id
            == "ST12F-PARAM-BINDING::" + policy.parameter_id
            and binding.calibration_optimizer_policy_ref
            in {
                ST12F_CALIBRATION_POLICY_ABSENCE_V1.value,
                "CALIBRATION::" + policy.parameter_id,
            }
            for policy, binding in zip(policies, bindings, strict=True)
        )
    )

    def calibration_join_valid(
        calibration: ST12FCalibrationOptimizerPolicyV1,
    ) -> bool:
        policy = registry.policy_by_parameter_id[calibration.parameter_id]
        binding = registry.binding_by_parameter_id[calibration.parameter_id]
        return (
            calibration.parameter_symbol == policy.parameter_symbol
            and calibration.policy_consumer_owner == policy.policy_consumer_owner
            and calibration.calibration_route == policy.calibration_route
            and calibration.hard_bounds == policy.hard_bounds
            and calibration.initialization_policy == policy.initialization_policy
            and calibration.revalidation_trigger == policy.revalidation_trigger
            and calibration.search_or_tuning_range == policy.search_or_tuning_range
            and calibration.fallback == policy.fallback
            and calibration.seed_policy == policy.seed_policy
            and calibration.warm_start_policy == policy.warm_start_policy
            and calibration.selected_method
            == policy.optimizer_and_optimizer_version["optimizer"]
            and calibration.method_version
            == policy.optimizer_and_optimizer_version["version"]
            and calibration.required_preexisting_receipt_fields
            == tuple(
                policy.optimizer_and_optimizer_version[
                    "required_receipt_fields"
                ]
            )
            and calibration.st12f_execution_authorized is False
            and binding.calibration_optimizer_policy_ref
            == "CALIBRATION::" + policy.parameter_id
        )

    calibration_id_set = set(calibration_ids)
    non_calibrated_policies = tuple(
        policy for policy in policies if policy.parameter_id not in calibration_id_set
    )
    calibration_and_absence_valid = (
        len(non_calibrated_policies) == 3046
        and all(calibration_join_valid(row) for row in calibrations)
        and all(
            registry.calibration_policy_or_absence_for_parameter_id(
                policy.parameter_id
            )
            is ST12F_CALIBRATION_POLICY_ABSENCE_V1
            and registry.binding_by_parameter_id[
                policy.parameter_id
            ].calibration_optimizer_policy_ref
            == ST12F_CALIBRATION_POLICY_ABSENCE_V1.value
            for policy in non_calibrated_policies
        )
    )
    repeated_ready_identity = initialize_st12f_parameter_registry_v1() is registry
    owner_package_equality_not_claimed = (
        receipt_type_valid and receipt.owner_package_equality_claimed is False
    )
    return (
        _check(
            "ARCH_ST12F_REGISTRY_RECEIPT_TYPES",
            registry_type_valid and receipt_type_valid,
            "exact frozen registry and immutable build-receipt types",
        ),
        _check(
            "ARCH_ST12F_RESOURCE_ROSTER_BOUNDS",
            roster_and_bounds_valid,
            "13 exact resources, 12 ordered shards, and certified byte bounds",
        ),
        _check(
            "ARCH_ST12F_RECEIPT_POPULATIONS",
            populations_valid,
            "3096 policies, 3096 bindings, 50 calibrations, 3046 absences",
        ),
        _check(
            "ARCH_ST12F_RESOLUTION_DISTRIBUTION",
            distribution_valid,
            "2668/300/78/38/12 exact resolution distribution",
        ),
        _check(
            "ARCH_ST12F_ORDERED_TYPED_ROWS",
            ordered_rows_valid,
            "ordered tuples contain exact frozen slots-enabled row types",
        ),
        _check(
            "ARCH_ST12F_IMMUTABLE_INDEX_SHAPES",
            index_shapes_valid,
            "four mapping-proxy indexes with counts 3096/3096/3096/50",
        ),
        _check(
            "ARCH_ST12F_INDEX_IDENTITY_CLOSURE",
            index_identity_valid,
            "every index key and object identity reconciles to ordered tuples",
        ),
        _check(
            "ARCH_ST12F_RECURSIVE_IMMUTABILITY",
            recursively_frozen_valid,
            "nested mappings are mapping proxies and sequences are tuples",
        ),
        _check(
            "ARCH_ST12F_OWNER_AND_FABRICATION_LAW",
            canonical_owner_and_fabrication_valid,
            "one canonical owner and no runtime value fabrication",
        ),
        _check(
            "ARCH_ST12F_RANGE_METADATA_NOT_RUNTIME_VALUE",
            range_metadata_not_runtime_valid,
            "search metadata remains distinct from typed resolution rules",
        ),
        _check(
            "ARCH_ST12F_POLICY_BINDING_JOINS",
            policy_binding_joins_valid,
            "all policy and application-binding identities reconcile",
        ),
        _check(
            "ARCH_ST12F_CALIBRATION_AND_ABSENCE_JOINS",
            calibration_and_absence_valid,
            "50 calibration joins and one singleton for 3046 absences",
        ),
        _check(
            "ARCH_ST12F_REPEATED_READY_IDENTITY",
            repeated_ready_identity,
            "repeated prewarm returns the same immutable ready registry",
        ),
        _check(
            "ARCH_ST12F_NO_OWNER_PACKAGE_EQUALITY_CLAIM",
            owner_package_equality_not_claimed,
            "owner_package_equality_claimed=False",
        ),
    )


def _st12f_parameter_registry_hot_path_ast_checks_v1(
) -> tuple[ValidationCheckV1, ...]:
    path = REPO_ROOT / (
        "src/qtt/stage1_prediction_markets/qku_computation_control_plane/"
        "parameter_policy.py"
    )
    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    module_functions = {
        node.name: node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
    }
    module_classes = {
        node.name: node for node in tree.body if isinstance(node, ast.ClassDef)
    }

    def call_name(node: ast.expr) -> str:
        if isinstance(node, ast.Name):
            return node.id
        if isinstance(node, ast.Attribute):
            prefix = call_name(node.value)
            return f"{prefix}.{node.attr}" if prefix else node.attr
        return ""

    def calls_in(nodes: tuple[ast.AST, ...]) -> tuple[str, ...]:
        return tuple(
            call_name(candidate.func)
            for root in nodes
            for candidate in ast.walk(root)
            if isinstance(candidate, ast.Call)
        )

    start = next(
        (
            index
            for index, node in enumerate(tree.body)
            if isinstance(node, ast.ClassDef)
            and node.name == "ST12FParameterRegistryInitializationStateV1"
        ),
        -1,
    )
    end = next(
        (
            index
            for index, node in enumerate(tree.body)
            if isinstance(node, ast.FunctionDef)
            and node.name == "_st12f_parameter_registry_build_receipt_v1"
        ),
        -1,
    )
    symbol_scope_valid = 0 <= start <= end
    section_nodes = tuple(tree.body[start : end + 1]) if symbol_scope_valid else ()
    initialization_names = {
        "load_st12f_parameter_registry_v1",
        "initialize_st12f_parameter_registry_v1",
        "_load_st12f_parameter_registry_state_machine_v1",
        "_st12f_build_complete_parameter_registry_v1",
    }
    module_level_initialization_calls = tuple(
        name
        for statement in tree.body
        if not isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
        for name in calls_in((statement,))
        if name.rsplit(".", 1)[-1] in initialization_names
    )
    load_function = module_functions.get("load_st12f_parameter_registry_v1")
    fast_path_shape_valid = False
    ready_fast_path_forbidden_calls: tuple[str, ...] = ()
    ready_fast_path_iteration_count = 0
    ready_fast_path_condition_context_count = 0
    if load_function is not None:
        pointer_assignment_index = next(
            (
                index
                for index, node in enumerate(load_function.body)
                if isinstance(node, ast.Assign)
                and any(
                    isinstance(target, ast.Name) and target.id == "ready"
                    for target in node.targets
                )
                and isinstance(node.value, ast.Name)
                and node.value.id == "_ST12F_PARAMETER_REGISTRY_READY_V1"
            ),
            -1,
        )
        fast_if_index = next(
            (
                index
                for index, node in enumerate(load_function.body)
                if isinstance(node, ast.If)
                and any(
                    isinstance(child, ast.Return)
                    and isinstance(child.value, ast.Name)
                    and child.value.id == "ready"
                    for child in node.body
                )
            ),
            -1,
        )
        delegation_index = next(
            (
                index
                for index, node in enumerate(load_function.body)
                if isinstance(node, ast.Return)
                and isinstance(node.value, ast.Call)
                and call_name(node.value.func)
                == "_load_st12f_parameter_registry_state_machine_v1"
            ),
            -1,
        )
        fast_path_shape_valid = (
            pointer_assignment_index == 0
            and fast_if_index == 1
            and delegation_index > fast_if_index
        )
        if pointer_assignment_index >= 0 and fast_if_index >= 0:
            fast_path_nodes = (
                load_function.body[pointer_assignment_index],
                load_function.body[fast_if_index],
            )
            ready_fast_path_forbidden_calls = calls_in(fast_path_nodes)
            ready_fast_path_iteration_count = sum(
                isinstance(
                    candidate,
                    (
                        ast.For,
                        ast.AsyncFor,
                        ast.ListComp,
                        ast.SetComp,
                        ast.DictComp,
                        ast.GeneratorExp,
                    ),
                )
                for root in fast_path_nodes
                for candidate in ast.walk(root)
            )
            ready_fast_path_condition_context_count = sum(
                isinstance(candidate, (ast.With, ast.AsyncWith))
                and any(
                    isinstance(name, ast.Name)
                    and name.id == "_ST12F_PARAMETER_REGISTRY_CONDITION_V1"
                    for name in ast.walk(candidate)
                )
                for root in fast_path_nodes
                for candidate in ast.walk(root)
            )
    registry_class = module_classes.get("ST12FParameterRegistryV1")
    accessor_names = {
        "parameter_policy_for_id": "policy_by_parameter_id",
        "application_binding_for_parameter_id": "binding_by_parameter_id",
        "application_binding_for_binding_id": "binding_by_binding_id",
        "calibration_policy_or_absence_for_parameter_id": (
            "calibration_by_parameter_id"
        ),
    }
    accessor_iteration_count = 0
    direct_accessor_count = 0
    if registry_class is not None:
        methods = {
            node.name: node
            for node in registry_class.body
            if isinstance(node, ast.FunctionDef)
        }
        for method_name, mapping_name in accessor_names.items():
            method = methods.get(method_name)
            if method is None:
                continue
            accessor_iteration_count += sum(
                isinstance(
                    node,
                    (
                        ast.For,
                        ast.AsyncFor,
                        ast.ListComp,
                        ast.SetComp,
                        ast.DictComp,
                        ast.GeneratorExp,
                    ),
                )
                for node in ast.walk(method)
            )
            mapping_access = any(
                (
                    isinstance(node, ast.Subscript)
                    and isinstance(node.value, ast.Attribute)
                    and isinstance(node.value.value, ast.Name)
                    and node.value.value.id == "self"
                    and node.value.attr == mapping_name
                )
                or (
                    isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr == "get"
                    and isinstance(node.func.value, ast.Attribute)
                    and isinstance(node.func.value.value, ast.Name)
                    and node.func.value.value.id == "self"
                    and node.func.value.attr == mapping_name
                )
                for node in ast.walk(method)
            )
            ordered_tuple_access = any(
                isinstance(node, ast.Attribute)
                and node.attr
                in {
                    "parameter_policies",
                    "application_bindings",
                    "calibration_policies",
                }
                for node in ast.walk(method)
            )
            if mapping_access and not ordered_tuple_access:
                direct_accessor_count += 1
    public_arbitrary_path_loaders = tuple(
        node.name
        for root in section_nodes
        for node in ast.walk(root)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and not node.name.startswith("_")
        and ("load" in node.name or "initialize" in node.name)
        and (
            any(
                token in argument.arg.lower()
                for argument in (*node.args.posonlyargs, *node.args.args)
                for token in ("path", "root", "directory", "filename", "resource")
            )
            or any(
                name.rsplit(".", 1)[-1] in {"open", "Path"}
                for name in calls_in((node,))
            )
        )
    )
    string_literals = tuple(
        node.value
        for root in section_nodes
        for node in ast.walk(root)
        if isinstance(node, ast.Constant) and isinstance(node.value, str)
    )
    runtime_codex_inputs_references = sum(
        ".codex_inputs" in value.lower() for value in string_literals
    )
    runtime_owner_zip_references = sum(
        "owner.zip" in value.lower() for value in string_literals
    )
    effect_prefixes = (
        "call_provider",
        "invoke_provider",
        "run_optimizer",
        "execute_optimizer",
        "optimize",
        "run_simulator",
        "simulate",
        "execute_qpu",
        "run_qpu",
        "activate_mode",
        "submit_order",
        "cancel_order",
        "amend_order",
        "release_order",
        "mutate_capital",
        "deploy",
    )
    effect_call_names = tuple(
        name
        for name in calls_in(section_nodes)
        if name.rsplit(".", 1)[-1].lower().startswith(effect_prefixes)
        or any(
            token in name.lower()
            for token in (
                "provider.",
                "optimizer.",
                "simulator.",
                "qpu.",
                "mode.",
                "order.",
                "capital.",
            )
        )
    )
    opaque_tokens = (
        "base85",
        "ascii85",
        "base64",
        "base32",
        "gzip",
        "zlib",
        "lzma",
        "bz2",
        "pickle",
        "marshal",
    )
    opaque_representation_count = sum(
        any(token in value.lower() for token in opaque_tokens)
        for value in (
            *string_literals,
            *calls_in(section_nodes),
            *(
                node.id
                for root in section_nodes
                for node in ast.walk(root)
                if isinstance(node, ast.Name)
            ),
        )
    )
    return (
        _check(
            "ARCH_ST12F_AST_MODULE_IMPORT_LAZY",
            symbol_scope_valid and not module_level_initialization_calls,
            "module_level_initialization_call_count="
            f"{len(module_level_initialization_calls)}",
        ),
        _check(
            "ARCH_ST12F_AST_READY_POINTER_FAST_RETURN",
            symbol_scope_valid and fast_path_shape_valid,
            "ready pointer is returned before state-machine delegation",
        ),
        _check(
            "ARCH_ST12F_AST_READY_FAST_PATH_NO_CALLS",
            fast_path_shape_valid
            and not ready_fast_path_forbidden_calls
            and ready_fast_path_iteration_count == 0
            and ready_fast_path_condition_context_count == 0,
            "ready_fast_path_forbidden_call_count="
            f"{len(ready_fast_path_forbidden_calls)}; "
            f"iteration_count={ready_fast_path_iteration_count}; "
            "condition_context_count="
            f"{ready_fast_path_condition_context_count}",
        ),
        _check(
            "ARCH_ST12F_AST_DIRECT_INDEX_ACCESSORS",
            direct_accessor_count == 4 and accessor_iteration_count == 0,
            f"direct_accessors={direct_accessor_count}; "
            f"public_accessor_iteration_count={accessor_iteration_count}",
        ),
        _check(
            "ARCH_ST12F_AST_NO_PUBLIC_ARBITRARY_PATH_LOADER",
            not public_arbitrary_path_loaders,
            "public_arbitrary_path_loader_count="
            f"{len(public_arbitrary_path_loaders)}",
        ),
        _check(
            "ARCH_ST12F_AST_NO_EXTERNAL_RUNTIME_PATH",
            runtime_codex_inputs_references == 0
            and runtime_owner_zip_references == 0,
            f"runtime_codex_inputs_reference_count={runtime_codex_inputs_references}; "
            f"runtime_owner_zip_reference_count={runtime_owner_zip_references}",
        ),
        _check(
            "ARCH_ST12F_AST_NO_RUNTIME_EFFECT_CALLS",
            not effect_call_names,
            f"runtime_effect_call_count={len(effect_call_names)}",
        ),
        _check(
            "ARCH_ST12F_AST_NO_OPAQUE_REPRESENTATION",
            opaque_representation_count == 0,
            f"opaque_representation_count={opaque_representation_count}",
        ),
    )


def validate_st12f_parameter_registry_v1() -> ValidationReportV1:
    registry = initialize_st12f_parameter_registry_v1()
    receipt = _st12f_parameter_registry_build_receipt_v1(registry)
    checks = (
        *_st12f_parameter_registry_integrity_checks_v1(registry, receipt),
        *_st12f_parameter_registry_hot_path_ast_checks_v1(),
    )
    report = ValidationReportV1("architecture", checks)
    report.assert_passed()
    return report


def _existing_owner_views_valid() -> bool:
    identity = RP5CIdentityAdapterV1(REPO_ROOT).get_formula("FORMULA_QKU")
    plugins = PR162EPluginAdapterV1(REPO_ROOT).load_families()
    quantum = PR162EQuantumAdapterV1(REPO_ROOT).load_mappings(
        QuantumModelKind.QUBO
    )
    projections = ExistingOwnerProjectionAdapterV1(REPO_ROOT)
    projection_views = (
        projections.load_readiness(),
        projections.load_pretrade(),
        projections.load_svc(),
        projections.load_agent_orch(),
    )
    source_scheduler = SourceRevalidationSchedulerAdapterV1.load_view()
    snapshot_boundary = LatencyHotPathSnapshotBoundaryAdapterV1.load_view()
    legacy = load_legacy_formula_comparators()
    if not plugins or not quantum or not legacy:
        return False
    consumed_owner_ids = {
        identity.source_owner,
        plugins[0].source_owner,
        quantum[0].source_owner,
        *(view.owner_id for view in projection_views),
        source_scheduler.owner_id,
        snapshot_boundary.owner_id,
        legacy[0].source_owner,
    }
    return (
        consumed_owner_ids == set(OWNER_IDS)
        and len(legacy) == 7
        and all(not view.exact_decimal_alias for view in legacy)
    )


def _architecture_checks() -> tuple[ValidationCheckV1, ...]:
    ids = tuple(IMPLEMENTATION_REGISTRY)
    st12f_parameter_registry_checks = validate_st12f_parameter_registry_v1().checks
    return (
        _check("ARCH_PRODUCTION_CORE_33", len(PRODUCTION_CORE_PATHS) == 33, "33 centralized validation paths including six ST12-F partitions"),
        _check("ARCH_OWNER_MAP_10", len(OWNER_IDS) == 10, "10 existing owners"),
        _check(
            "ARCH_IMPLEMENTATION_REGISTRY_30",
            ids == ST12B_MATH_IDS,
            repr(ids),
        ),
        _check(
            "ARCH_MATH_SPECIFICATIONS_30_VALUE_LEVEL",
            all(
                record.specification_metadata.certified_formula
                and record.specification_metadata.domain_and_fail_closed_guards
                and record.specification_metadata.implementation_algorithm
                and record.specification_metadata.mandatory_comparator_or_reconciliation
                and record.specification_metadata.precision_and_rounding_policy
                and record.specification_metadata.optional_library_adapter_policy
                and record.specification_metadata.tie_break_policy
                for record in IMPLEMENTATION_REGISTRY.values()
            ),
            "all 30 implementations carry complete frozen math metadata",
        ),
        _check(
            "ARCH_PARAMETER_POLICY_479",
            len(CUMULATIVE_PARAMETER_POLICIES) == 479
            and len(PARAMETER_POLICIES) == 135,
            f"{len(CUMULATIVE_PARAMETER_POLICIES)} cumulative rows; "
            f"{len(PARAMETER_POLICIES)} preserved Tranche-A rows",
        ),
        _check(
            "ARCH_ORACLE_PACK_30",
            tuple(ORACLE_BY_MATH_ID) == ST12B_MATH_IDS
            and tuple(GOLDEN_VECTOR_BY_MATH_ID) == ST12B_MATH_IDS,
            "oracle and vector ids align",
        ),
        _check(
            "ARCH_SINGLE_REGISTRY",
            len({id(IMPLEMENTATION_REGISTRY)}) == 1,
            "one immutable implementation registry",
        ),
        _check(
            "ARCH_PARAMETER_SEEDS_135_VALUE_LEVEL",
            _parameter_seed_resolution_valid(),
            "all 135 exact seed rows resolve with frozen metadata",
        ),
        *st12f_parameter_registry_checks,
        _check(
            "ARCH_EXISTING_OWNERS_10_CONSUMED",
            _existing_owner_views_valid(),
            "all ten canonical owners are consumed through immutable views",
        ),
        _check(
            "ARCH_OPERATION_CONTRACTS_15",
            len(validate_operation_contract_closure()) == 15,
            "15 complete collision-free data-only operation contracts",
        ),
        _check(
            "ARCH_ST12B_FROZEN_MANIFEST",
            validate_tranche_b_frozen_manifest().passed,
            "30 formulas, 479 parameters, 142 input owners, 6 dependencies, "
            "90 vectors, and 1,351 non-orphan routes",
        ),
    )


def _operations_checks() -> tuple[ValidationCheckV1, ...]:
    authority = CapabilityEnvelopeV1()
    assert_no_effect_authority(authority)
    return (
        _check(
            "OPS_AUTHORITY_ALL_FALSE",
            not any(getattr(authority, item.name) for item in fields(authority)),
            "all capabilities are false",
        ),
        _check(
            "OPS_CONTRACT_ONLY",
            _contract_only_models_are_valid(),
            "typed configuration, health, supervision, fallback, snapshot, "
            "transaction, and receipt contracts deny effects",
        ),
        _check(
            "OPS_NO_RUNTIME_TOPOLOGY",
            _no_runtime_topology(),
            "AST and exact package names contain no runtime topology",
        ),
        _check(
            "OPS_ST12B_EFFECTIVE_CAPABILITIES",
            tuple(ST12B_OPERATION_CAPABILITY_BY_ID.values()).count(
                OperationCapabilityClass.PURE_DETERMINISTIC_COMPUTATION
            )
            == 8
            and tuple(ST12B_OPERATION_CAPABILITY_BY_ID.values()).count(
                OperationCapabilityClass.READ_ONLY_PROJECTION
            )
            == 2
            and tuple(ST12B_OPERATION_CAPABILITY_BY_ID.values()).count(
                OperationCapabilityClass.NO_EFFECT_RECORD
            )
            == 2
            and tuple(ST12B_OPERATION_CAPABILITY_BY_ID.values()).count(
                OperationCapabilityClass.CONTRACT_DEFINITION_ONLY
            )
            == 3,
            "one existing schema owner projects 8 pure, 2 read-only, "
            "2 no-effect, and 3 held capabilities",
        ),
    )


def _quantum_checks() -> tuple[ValidationCheckV1, ...]:
    quantum_ids = tuple(value for value in MATH_IDS if int(value.split("-")[1]) >= 46)
    optional_metadata = {
        row.currentization_id: json.loads(row.exact_facts_json)
        for row in SOURCE_CURRENTIZATION_OVERLAYS
        if row.currentization_id.startswith("ST12A-CURR-DEPENDENCY")
    }
    return (
        _check(
            "QUANTUM_MATH_4",
            quantum_ids == ("MATH-46", "MATH-47", "MATH-48", "MATH-49"),
            repr(quantum_ids),
        ),
        _check(
            "QUANTUM_OPTIONAL_METADATA_ONLY",
            "ST12A-CURR-DEPENDENCY-002" in optional_metadata
            and "ST12A-CURR-DEPENDENCY-003" in optional_metadata,
            "Qiskit Optimization and D-Wave remain metadata only",
        ),
        _check(
            "QUANTUM_ST12B_STRUCTURAL_READINESS_4",
            tuple(QUANTUM_STRUCTURAL_READINESS_BY_MATH_ID) == quantum_ids
            and not any(
                row.qpu_or_simulator_authority
                for row in QUANTUM_STRUCTURAL_READINESS_BY_MATH_ID.values()
            ),
            "four executable structural contracts with zero simulator/QPU authority",
        ),
        _check(
            "QUANTUM_NO_BACKEND",
            all(
                not entry.provider_or_qpu_effect_allowed
                for math_id, entry in IMPLEMENTATION_REGISTRY.items()
                if math_id in quantum_ids
            ),
            "all quantum entries deny backend effects",
        ),
    )


def _security_checks() -> tuple[ValidationCheckV1, ...]:
    unsafe_paths = (
        "../escape",
        "/absolute",
        r"C:\absolute",
        r"folder\..\escape",
        "folder//file",
        "folder/./file",
        "folder/NUL.txt",
        "folder/trailing.",
        "folder/stream:name",
    )
    rejected = 0
    for path in unsafe_paths:
        try:
            validate_relative_path(path)
        except ComputationControlPlaneError:
            rejected += 1
    return (
        _check("SECURITY_PATH_TRAVERSAL", rejected == len(unsafe_paths), str(rejected)),
        _check(
            "SECURITY_DEFAULT_DENY",
            not any(
                getattr(CapabilityEnvelopeV1(), item.name)
                for item in fields(CapabilityEnvelopeV1())
            ),
            "all authority fields false",
        ),
        _check(
            "SECURITY_NO_DYNAMIC_IMPORT",
            _no_dynamic_import_or_unsafe_deserialization(),
            "AST contains no dynamic import, eval, exec, or unsafe deserialization",
        ),
    )


