@dataclass(frozen=True, slots=True)
class AgentConsumerDAGRowV1:
    edge_id: str
    edge_kind: str
    upstream_owner: str
    exact_selector: str
    transformation: str
    canonical_owner: str
    responsible_agent: str
    service_operation: str
    downstream_consumer: str | tuple[str, ...]
    subject_id: str
    terminal_route: str
    test: str
    validator: str
    orphan_state: bool

    def __post_init__(self) -> None:
        for name in (
            "edge_id",
            "edge_kind",
            "upstream_owner",
            "exact_selector",
            "transformation",
            "canonical_owner",
            "responsible_agent",
            "service_operation",
            "subject_id",
            "terminal_route",
            "test",
            "validator",
        ):
            value = getattr(self, name)
            if not isinstance(value, str) or not value:
                raise ContractValidationError(
                    ReasonCode.INVALID_CONTRACT,
                    f"agent/consumer DAG field {name} must be nonempty text",
                )
        if self.responsible_agent not in ST12B_AGENT_IDS:
            raise ContractValidationError(
                ReasonCode.INVALID_CONTRACT,
                f"unregistered Tranche-B agent: {self.responsible_agent}",
            )
        if isinstance(self.downstream_consumer, tuple):
            if (
                not self.downstream_consumer
                or any(
                    not isinstance(value, str) or not value
                    for value in self.downstream_consumer
                )
                or len(set(self.downstream_consumer))
                != len(self.downstream_consumer)
            ):
                raise ContractValidationError(
                    ReasonCode.INVALID_CONTRACT,
                    "agent/consumer DAG consumer tuple is invalid",
                )
        elif (
            not isinstance(self.downstream_consumer, str)
            or not self.downstream_consumer
        ):
            raise ContractValidationError(
                ReasonCode.INVALID_CONTRACT,
                "agent/consumer DAG consumer must be nonempty text or tuple",
            )
        if type(self.orphan_state) is not bool or self.orphan_state:
            raise ContractValidationError(
                ReasonCode.INVALID_CONTRACT,
                f"agent/consumer DAG edge must terminate: {self.edge_id}",
            )


def _agent_consumer_row(row: Mapping[str, object]) -> AgentConsumerDAGRowV1:
    consumer = row["downstream_consumer"]
    if isinstance(consumer, list):
        normalized_consumer: str | tuple[str, ...] = tuple(
            str(value) for value in consumer
        )
    else:
        normalized_consumer = str(consumer)
    return AgentConsumerDAGRowV1(
        edge_id=str(row["edge_id"]),
        edge_kind=str(row["edge_kind"]),
        upstream_owner=str(row["upstream_owner"]),
        exact_selector=str(row["exact_selector"]),
        transformation=str(row["transformation"]),
        canonical_owner=str(row["canonical_owner"]),
        responsible_agent=str(row["responsible_agent"]),
        service_operation=str(row["service_operation"]),
        downstream_consumer=normalized_consumer,
        subject_id=str(row["subject_id"]),
        terminal_route=str(row["terminal_route"]),
        test=str(row["test"]),
        validator=str(row["validator"]),
        orphan_state=row["orphan_state"] is True,
    )


ST12B_AGENT_CONSUMER_DAG = tuple(
    _agent_consumer_row(row)
    for row in json.loads(_ST12B_AGENT_CONSUMER_DAG_JSON)
)
AGENT_CONSUMER_DAG = ST12B_AGENT_CONSUMER_DAG
AGENT_CONSUMER_DAG_BY_EDGE_ID: Mapping[
    str, AgentConsumerDAGRowV1
] = MappingProxyType(
    {row.edge_id: row for row in ST12B_AGENT_CONSUMER_DAG}
)

_ST12B_DAG_EDGE_KIND_COUNTS = {
    "FORMULA_SPECIFICATION_TO_CENTRAL_EXECUTION_CONTRACT": 30,
    "NUMERIC_VALUE_OWNER_TO_FORMULA_INPUT": 142,
    "DATA_FLOW_EDGE": 1,
    "CALLABLE_OR_SUBROUTINE_DEPENDENCY": 4,
    "SHARED_POLICY_OR_METHOD_DEPENDENCY": 1,
    "PARAMETER_POLICY_TO_CENTRAL_COMPILER": 479,
    "PARAMETER_POLICY_TO_ULTIMATE_BEHAVIOR_OR_HELD_OWNER": 479,
    "RUNTIME_VALUE_OWNER_TO_PARAMETER_POLICY": 190,
    "PARAMETER_TO_DIRECT_FORMULA_POLICY": 25,
}
if (
    len(ST12B_AGENT_CONSUMER_DAG) != 1351
    or len(AGENT_CONSUMER_DAG_BY_EDGE_ID) != 1351
    or Counter(row.edge_kind for row in ST12B_AGENT_CONSUMER_DAG)
    != _ST12B_DAG_EDGE_KIND_COUNTS
):
    raise ContractValidationError(
        ReasonCode.INVALID_CONTRACT,
        "the frozen agent/consumer DAG must retain all 1,351 exact routes",
    )


def validate_tranche_b_frozen_manifest() -> ValidationReportV1:
    from .bindings import (
        FORMULA_INPUT_AUTHORITY_BINDINGS,
        FROZEN_ONLINE_CURRENTIZATION_RECEIPTS,
        NUMERIC_VALUE_AUTHORITY_BINDINGS,
        PRIMARY_SOURCE_REGISTRY,
        SOURCE_CONFLICT_RESOLUTIONS,
        SOURCE_CURRENTIZATION_REGISTRY,
        SOURCE_POPULATION_COUNTS,
    )
    from .dependency_graph import FROZEN_DEPENDENCY_RELATIONSHIPS
    from .implementation_registry import IMPLEMENTATION_VERSION_REGISTRY
    from .oracle_contracts import ST12B_PROPERTY_TESTS, ST12B_VECTOR_PACK
    from .parameter_policy import (
        INCREMENTAL_TRANCHE_B_PARAMETER_POLICIES,
        OPTIMIZER_DEFAULT_CURRENTIZATIONS,
        RUNTIME_PARAMETER_OWNER_BINDINGS,
    )
    from .quantum_adapter import QUANTUM_STRUCTURAL_READINESS_BY_MATH_ID
    from .specification import (
        FROZEN_FORMULA_INPUT_CONTRACTS,
        FROZEN_FORMULA_REQUIREMENTS,
        FROZEN_FORMULA_REPOSITORY_DISPOSITIONS,
        FROZEN_NAMED_OUTPUT_CONTRACTS,
    )
    from .stack_resolver import REGISTERED_FORMULA_STACKS

    output_member_count = sum(
        len(contract.members)
        for contract in FROZEN_NAMED_OUTPUT_CONTRACTS.values()
    )
    formula_dispositions = Counter(
        row.disposition
        for row in FROZEN_FORMULA_REPOSITORY_DISPOSITIONS.values()
    )
    dependency_kinds = Counter(
        row.kind.value for row in FROZEN_DEPENDENCY_RELATIONSHIPS.values()
    )
    numeric_subject_kinds = Counter(
        row.subject_kind for row in NUMERIC_VALUE_AUTHORITY_BINDINGS.values()
    )
    dag_responsible_agents = {
        row.responsible_agent for row in ST12B_AGENT_CONSUMER_DAG
    }
    checks = (
        _check(
            "ST12B_FORMULAS_30",
            len(FROZEN_FORMULA_REQUIREMENTS) == 30
            and len(FROZEN_FORMULA_INPUT_CONTRACTS) == 30
            and len(FROZEN_FORMULA_REPOSITORY_DISPOSITIONS) == 30
            and len(IMPLEMENTATION_REGISTRY) == 30,
            "30 exact formula identities and active implementations",
        ),
        _check(
            "ST12B_FORMULA_DISPOSITIONS_10_9_11",
            formula_dispositions
            == {
                "REUSE_EXISTING_EXACT_VERSION": 10,
                "REGISTER_SEMANTIC_SUCCESSOR": 9,
                "NEW_TRANCHE_B_IMPLEMENTATION": 11,
            }
            and len(IMPLEMENTATION_VERSION_REGISTRY) == 39,
            "10 exact reuses, 9 semantic successors, 11 new implementations, "
            "and 39 active-plus-preserved version records",
        ),
        _check(
            "ST12B_OUTPUTS_30_MEMBERS_130",
            len(FROZEN_NAMED_OUTPUT_CONTRACTS) == 30
            and output_member_count == 130,
            f"{output_member_count} named record members",
        ),
        _check(
            "ST12B_INPUT_OWNER_INTERFACES_142",
            len(FORMULA_INPUT_AUTHORITY_BINDINGS) == 142,
            f"{len(FORMULA_INPUT_AUTHORITY_BINDINGS)} exact interfaces",
        ),
        _check(
            "ST12B_PARAMETERS_479_344_190",
            len(CUMULATIVE_PARAMETER_POLICIES) == 479
            and len(INCREMENTAL_TRANCHE_B_PARAMETER_POLICIES) == 344
            and len(RUNTIME_PARAMETER_OWNER_BINDINGS) == 190,
            "479 cumulative, 344 incremental, 190 runtime-owned",
        ),
        _check(
            "ST12B_PARAMETER_APPLICATION_CLOSURE_479",
            len(OPTIMIZER_DEFAULT_CURRENTIZATIONS) == 479
            and all(
                row.application_binding_id == f"PAB::{parameter_id}"
                and row.ultimate_binding_id == f"PUCB::{parameter_id}"
                and row.ultimate_consumer[
                    "generic_compiler_is_sole_terminal_consumer"
                ]
                is False
                for parameter_id, row in CUMULATIVE_PARAMETER_POLICIES.items()
            ),
            "479 optimizer/default currentizations and exact non-compiler "
            "terminal application owners",
        ),
        _check(
            "ST12B_SOURCES_55_CURRENTIZATION_1_7_5",
            len(PRIMARY_SOURCE_REGISTRY) == 55
            and dict(SOURCE_POPULATION_COUNTS)
            == {
                "EXTERNAL_PRIMARY_OR_OFFICIAL_SOURCE": 24,
                "OWNER_FORMAL_DERIVATION": 30,
                "OWNER_ARCHITECTURE_OR_POLICY": 1,
            }
            and len(SOURCE_CONFLICT_RESOLUTIONS) == 1
            and len(SOURCE_CURRENTIZATION_REGISTRY) == 7
            and len(FROZEN_ONLINE_CURRENTIZATION_RECEIPTS) == 5,
            "55 exact sources (24 external, 30 formal, 1 owner architecture), "
            "1 conflict, 7 source currentizations, and 5 frozen online receipts",
        ),
        _check(
            "ST12B_NUMERIC_VALUE_AUTHORITIES_621",
            len(NUMERIC_VALUE_AUTHORITY_BINDINGS) == 621
            and numeric_subject_kinds
            == {"PARAMETER": 479, "FORMULA_INPUT": 142},
            "621 exact value-authority rows = 479 parameters + 142 formula inputs",
        ),
        _check(
            "ST12B_DEPENDENCIES_6",
            len(FROZEN_DEPENDENCY_RELATIONSHIPS) == 6
            and dependency_kinds
            == {
                "DATA_FLOW_EDGE": 1,
                "CALLABLE_OR_SUBROUTINE_DEPENDENCY": 4,
                "SHARED_POLICY_OR_METHOD_DEPENDENCY": 1,
            }
            and tuple(REGISTERED_FORMULA_STACKS)
            == ("STACK::MATH-01::MATH-02::V3_4",),
            "6 exact relationships (1 data, 4 callable, 1 shared policy) "
            "and the sole MATH-01 to MATH-02 stack",
        ),
        _check(
            "ST12B_ORACLES_30_VECTORS_90_PROPERTIES_30",
            len(ORACLE_BY_MATH_ID) == 30
            and len(ST12B_VECTOR_PACK) == 90
            and len(ST12B_PROPERTY_TESTS) == 30,
            "complete frozen independent-oracle contract matrix",
        ),
        _check(
            "ST12B_AGENT_DAG_1351",
            len(AGENT_CONSUMER_DAG_BY_EDGE_ID) == 1351
            and not any(row.orphan_state for row in ST12B_AGENT_CONSUMER_DAG),
            "all exact routes terminate without orphan state",
        ),
        _check(
            "ST12B_AGENT_IDENTITIES_8",
            ST12B_AGENT_IDS
            == (
                "research_agent",
                "parameter_selector_agent",
                "risk_manager_agent",
                "quantum_optimizer_agent",
                "commander_agent",
                "governance_agent",
                "dashboard_agent",
                "connector_venue_readiness_future_consumer",
            )
            and dag_responsible_agents <= set(ST12B_AGENT_IDS)
            and set(ST12B_AGENT_IDS) - dag_responsible_agents
            == {"dashboard_agent"},
            "eight current identities; DAG responsibility is closed and the "
            "dashboard remains a read-only consumer identity",
        ),
        _check(
            "ST12B_OPERATIONS_8_2_2_3",
            Counter(ST12B_OPERATION_CAPABILITY_BY_ID.values())
            == {
                OperationCapabilityClass.PURE_DETERMINISTIC_COMPUTATION: 8,
                OperationCapabilityClass.READ_ONLY_PROJECTION: 2,
                OperationCapabilityClass.NO_EFFECT_RECORD: 2,
                OperationCapabilityClass.CONTRACT_DEFINITION_ONLY: 3,
            },
            "one existing 15-operation roster projects 8 pure, 2 read-only, "
            "2 no-effect, and 3 held capabilities",
        ),
        _check(
            "ST12B_QUANTUM_STRUCTURAL_4_NO_QPU",
            tuple(QUANTUM_STRUCTURAL_READINESS_BY_MATH_ID)
            == ("MATH-46", "MATH-47", "MATH-48", "MATH-49")
            and not any(
                row.qpu_or_simulator_authority
                for row in QUANTUM_STRUCTURAL_READINESS_BY_MATH_ID.values()
            ),
            "four structural quantum mappings with no simulator or QPU authority",
        ),
    )
    return ValidationReportV1("tranche_b", checks)


def _st12e_closure(
    control_id: str,
    control_slug: str,
    predicate_group: str,
    semantic_owner: str,
) -> Mapping[str, object]:
    domain = control_id.split("::", 1)[0].removeprefix("ST11-").casefold()
    return MappingProxyType(
        {
            "closure_id": f"ST12-CLOSURE::{control_id}",
            "control_id": control_id,
            "domain": domain,
            "control_slug": control_slug,
            "predicate_group": predicate_group,
            "semantic_owner": semantic_owner,
            "validator_owner": (
                "tools/independent_validate_qku_computation_control_plane_e.py"
            ),
        }
    )


